<?= $this->extend('layout') ?><?= $this->section('content') ?><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/pivottable/2.23.0/pivot.min.css"><style>.tdc-panel,#pivot-container{background:var(--bg-card);border:1px solid var(--border);border-radius:12px;padding:16px;margin:14px 0}.tdc-panel{display:flex;gap:12px;flex-wrap:wrap;align-items:end}.tg{display:grid;gap:5px}.tg label{font-size:.68rem;color:var(--text-muted);text-transform:uppercase}.tg select{min-width:120px}.age-filter{border-radius:20px;padding:6px 12px;font-size:.75rem}.loading{height:145px;display:grid;place-content:center;text-align:center;color:var(--text-muted);gap:8px}</style><div class="dv-page-header"><h1><i class="bi bi-table" style="color:var(--accent)"></i> Tableau Croisé Dynamique</h1><div class="dv-breadcrumb"><a href="<?= site_url('/') ?>">Accueil</a><span>›</span><span>TDC</span></div></div><div class="tdc-panel"><div class="tg"><label>Agrégateur</label><select class="dv-select" id="agg"><option>Count</option><option>Sum</option><option>Average</option></select></div><div class="tg"><label>Ligne par défaut</label><select class="dv-select" id="row"><option>TypeMedicament</option><option>District</option><option>Genre</option></select></div><div class="tg"><label>Colonne par défaut</label><select class="dv-select" id="col"><option>Genre</option><option>District</option><option>Mois</option></select></div><div class="tg"><label>Unité âge</label><select class="dv-select" id="unit"><option value="months">Mois</option><option value="years">Années</option></select></div><label class="dv-radio-label"><input id="autoAge" type="checkbox" checked> Calcul tranche_âge auto</label><div style="flex-basis:100%;border-top:1px solid var(--border)"></div><button class="dv-btn dv-btn-primary" id="load"><i class="bi bi-play-fill"></i> Charger les données</button><button class="dv-btn dv-btn-outline" id="csv"><i class="bi bi-download"></i> Exporter CSV</button><button class="dv-btn dv-btn-outline" id="reset"><i class="bi bi-arrow-counterclockwise"></i> Réinitialiser</button><button class="dv-btn dv-btn-success" id="sample"><i class="bi bi-database"></i> Données exemple</button></div><div class="tdc-panel"><div class="tg"><label>Filtre rapide — tranche d'âge</label><div id="filters"><button class="dv-btn dv-btn-primary age-filter" data-age="">Toutes</button><button class="dv-btn dv-btn-outline age-filter" data-age="2-6 mois">2–6 mois</button><button class="dv-btn dv-btn-outline age-filter" data-age="6-11 mois">6–11 mois</button><button class="dv-btn dv-btn-outline age-filter" data-age="1-5 ans">1–5 ans</button><button class="dv-btn dv-btn-outline age-filter" data-age="5-12 ans">5–12 ans</button><button class="dv-btn dv-btn-outline age-filter" data-age="12-25 ans">12–25 ans</button><button class="dv-btn dv-btn-outline age-filter" data-age="25 ans +">25 ans +</button></div></div></div><div id="pivot-container"><div class="loading"><i class="bi bi-hourglass-split" style="font-size:2rem"></i><span>Chargement en cours…</span></div></div><script src="https://cdnjs.cloudflare.com/ajax/libs/jquery/3.6.0/jquery.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/jqueryui/1.12.1/jquery-ui.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/pivottable/2.23.0/pivot.min.js"></script><script>let records=[];function tranche(a){a=+a;if(a<=6)return'2-6 mois';if(a<=11)return'6-11 mois';if(a<=59)return'1-5 ans';if(a<=143)return'5-12 ans';if(a<=299)return'12-25 ans';return'25 ans +'}function render(d){d=d.map(x=>({...x,Tranche_Age:tranche(x.Age)}));$('#pivot-container').pivotUI(d,{rows:[row.value],cols:[col.value],aggregatorName:agg.value,vals:agg.value==='Count'?[]:['Quantite'],rendererName:'Table'},true)}load.onclick=()=>fetch('<?= site_url('api/donnees') ?>').then(x=>x.json()).then(x=>{records=x;render(x)});sample.onclick=()=>{records=[{Age:4,Genre:'Feminin',District:'Antananarivo',TypeMedicament:'Antibiotique',Quantite:3,Mois:'2026-08'}];render(records)};reset.onclick=()=>pivotContainer.innerHTML='<div class="loading"><i class="bi bi-hourglass-split"></i><span>Chargement en cours…</span></div>';filters.onclick=e=>{if(e.target.dataset.age!==undefined)render(e.target.dataset.age?records.filter(x=>tranche(x.Age)===e.target.dataset.age):records)};csv.onclick=()=>{let t=[...document.querySelectorAll('#pivot-container tr')].map(r=>[...r.cells].map(c=>c.innerText).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([t],{type:'text/csv'}));a.download='tdc.csv';a.click()};load.onclick()</script><?= $this->endSection() ?>
